--   core_refresh_tokens / core_sessions / core_guides / core_faqs / core_migration_history
-- (their RLS policies were created by the first run; NULL rows remain visible via the
--  policy's `tenant_id IS NULL` branch, preserving current behavior.)
-- Pre-backfill: mes.production_schedules had 50 rows with NULL tenant_id -> nil
UPDATE mes.production_schedules SET tenant_id = '00000000-0000-0000-0000-000000000000'::uuid WHERE tenant_id IS NULL;

