    END IF;
    EXECUTE format('ALTER TABLE %I.%I FORCE ROW LEVEL SECURITY', split_part(t, '.', 1), split_part(t, '.', 2));
    RAISE NOTICE 'rls enabled: %', t;
  END LOOP;
END $$;

